__hydrateVak("vmbo","bi",{"A":{"sv":[{"v":"Cellen met dezelfde vorm en functie vormen samen...","o":["een orgaan","een weefsel","een orgaanstelsel","een organisme"],"c":1,"d":2,"u":"Cellen met dezelfde vorm en functie vormen een weefsel.","uo":["Een orgaan bestaat uit meerdere weefsels.","Klopt: gelijke cellen vormen een weefsel.","Een orgaanstelsel is een groep samenwerkende organen.","Een organisme is het hele levende wezen."],"uh":"Cel → weefsel → orgaan → orgaanstelsel."},{"v":"Het hart bestaat uit spierweefsel, zenuwweefsel en bloedvaten. Het hart is dus...","o":["een cel","een weefsel","een orgaan","een orgaanstelsel"],"c":2,"d":2,"u":"Een orgaan bestaat uit meerdere weefsels die samen een taak hebben.","uo":["Een cel is de kleinste bouwsteen.","Een weefsel is één soort cellen.","Klopt: meerdere weefsels vormen een orgaan.","Een orgaanstelsel is een groep organen."],"uh":"Orgaan = meerdere weefsels met een taak."},{"v":"Je ziet onder de microscoop een cel met een celwand en bladgroenkorrels. Wat voor cel is dit?","o":["Een dierlijke cel","Een zenuwcel","Een rode bloedcel","Een plantencel"],"c":3,"d":3,"u":"Alleen plantencellen hebben een celwand en bladgroenkorrels.","uo":["Een dierlijke cel heeft geen celwand.","Een zenuwcel is een dierlijke cel.","Een rode bloedcel is een dierlijke cel.","Klopt: celwand en bladgroen horen bij planten."],"uh":"Celwand + bladgroen = plantencel."},{"v":"Welk onderdeel heeft een plantencel wél en een dierlijke cel niet?","o":["Een celwand","Een celkern","Een celmembraan","Cytoplasma"],"c":0,"d":2,"u":"De celwand komt alleen bij plantencellen voor.","uo":["Klopt: de celwand is er bij planten.","Een celkern zit in beide.","Een celmembraan zit in beide.","Cytoplasma zit in beide."],"uh":"Celwand: alleen bij planten."},{"v":"Waar in de cel ligt het DNA?","o":["In het cytoplasma","In de celkern","In het celmembraan","In de vacuole"],"c":1,"d":1,"u":"Het DNA ligt in de celkern.","uo":["Het cytoplasma is de vloeistof eromheen.","Klopt: het DNA ligt in de celkern.","Het celmembraan is de buitenkant.","De vacuole is een vochtblaas in planten."],"uh":"DNA zit in de celkern."},{"v":"Hoe heet het dunne laagje dat de hele cel omsluit?","o":["De celkern","De celwand","Het celmembraan","Het cytoplasma"],"c":2,"d":1,"u":"Het celmembraan omsluit de cel en regelt wat er in en uit gaat.","uo":["De celkern bevat het DNA.","De celwand zit alleen bij planten.","Klopt: het celmembraan omsluit de cel.","Cytoplasma is de vloeistof in de cel."],"uh":"Celmembraan = omhulsel van de cel."},{"v":"Wat is de functie van de bladgroenkorrels in een plantencel?","o":["Het DNA bewaren","De cel stevig maken","Vocht opslaan","Fotosynthese uitvoeren"],"c":3,"d":2,"u":"In de bladgroenkorrels vindt de fotosynthese plaats.","uo":["Het DNA zit in de celkern.","De celwand maakt de cel stevig.","De vacuole slaat vocht op.","Klopt: bladgroen doet de fotosynthese."],"uh":"Bladgroenkorrel = fotosynthese."},{"v":"Hoe heet een stukje DNA met de code voor één eigenschap?","o":["Een gen","Een chromosoom","Een cel","Een weefsel"],"c":0,"d":1,"u":"Een gen is een stukje DNA met de code voor één eigenschap.","uo":["Klopt: een gen codeert voor één eigenschap.","Een chromosoom is opgerold DNA.","Een cel is de bouwsteen van het lichaam.","Een weefsel is een groep cellen."],"uh":"Gen = code voor één eigenschap."},{"v":"Wat is een chromosoom?","o":["De vloeistof in de cel","Sterk opgerold DNA","Het omhulsel van de cel","Een soort weefsel"],"c":1,"d":2,"u":"Een chromosoom is sterk opgerold DNA in de celkern.","uo":["De vloeistof in de cel is cytoplasma.","Klopt: een chromosoom is opgerold DNA.","Het omhulsel is het celmembraan.","Een weefsel is een groep cellen."],"uh":"Chromosoom = opgerold DNA."},{"v":"Iemand heeft blauwe ogen. Die blauwe ogen zijn een voorbeeld van het...","o":["genotype","gen","fenotype","chromosoom"],"c":2,"d":2,"u":"Het fenotype is wat je aan de buitenkant ziet, zoals oogkleur.","uo":["Het genotype is de erfelijke aanleg die je niet ziet.","Een gen is een stukje DNA.","Klopt: wat je ziet is het fenotype.","Een chromosoom is opgerold DNA."],"uh":"Fenotype = wat je ziet."},{"v":"Wat wordt bedoeld met het genotype van een organisme?","o":["De zichtbare eigenschappen","Het aantal cellen","De grootte","De erfelijke aanleg (de genen)"],"c":3,"d":2,"u":"Het genotype is de erfelijke aanleg: alle genen samen.","uo":["De zichtbare eigenschappen zijn het fenotype.","Het aantal cellen zegt niets over het genotype.","De grootte hoort bij het fenotype.","Klopt: het genotype is de erfelijke aanleg."],"uh":"Genotype = de genen."},{"v":"Je kruist twee planten met genotype Aa. A (rood) is dominant over a (wit). Welk deel is naar verwachting wit?","o":["1 op de 4","2 op de 4","3 op de 4","4 op de 4"],"c":0,"d":3,"u":"Aa × Aa geeft AA, Aa, Aa en aa: 1 op de 4 is aa (wit).","uo":["Klopt: alleen aa is wit, dus 1 op de 4.","2 op de 4 klopt niet, alleen aa is wit.","3 op de 4 is juist rood.","Niet alle nakomelingen zijn wit."],"uh":"Aa × Aa → 3 : 1."},{"v":"Een plant heeft genotype Bb. B (paars) is dominant over b (wit). Welke kleur heeft de plant?","o":["Wit","Paars","Half paars, half wit","Geen kleur"],"c":1,"d":3,"u":"Het dominante allel B bepaalt de kleur, dus de plant is paars.","uo":["Wit zou alleen bij genotype bb.","Klopt: het dominante B maakt de plant paars.","Kleuren mengen niet bij dominantie.","Elke plant heeft een kleur."],"uh":"Het dominante allel bepaalt het fenotype."},{"v":"Een eigenschap komt alleen tot uiting als beide allelen ervoor aanwezig zijn. Zo'n allel noem je...","o":["dominant","een chromosoom","recessief","een fenotype"],"c":2,"d":2,"u":"Een recessief allel komt alleen tot uiting bij twee exemplaren.","uo":["Een dominant allel is al bij één exemplaar zichtbaar.","Een chromosoom is opgerold DNA.","Klopt: recessief heeft er twee nodig.","Een fenotype is een zichtbare eigenschap."],"uh":"Recessief = alleen dubbel zichtbaar."},{"v":"Konijnen met een dikke vacht overleven de kou beter en krijgen meer jongen. Dit heet...","o":["fotosynthese","een kruising","celdeling","natuurlijke selectie"],"c":3,"d":3,"u":"Bij natuurlijke selectie overleven de best aangepaste individuen en geven hun eigenschappen door.","uo":["Fotosynthese is het maken van voedsel door planten.","Een kruising combineert twee ouders.","Celdeling is het delen van een cel.","Klopt: de best aangepaste konijnen overleven."],"uh":"Best aangepast overleeft: natuurlijke selectie."},{"v":"Waarom lijken kinderen vaak op hun ouders?","o":["Doordat ze DNA van hun ouders erven","Doordat ze hetzelfde eten","Doordat ze in hetzelfde huis wonen","Doordat ze evenveel cellen hebben"],"c":0,"d":2,"u":"Kinderen erven DNA (genen) van hun ouders, met daarin de erfelijke eigenschappen.","uo":["Klopt: ze erven het DNA van hun ouders.","Wat je eet verandert je DNA niet.","Waar je woont bepaalt je genen niet.","Iedereen heeft heel veel cellen."],"uh":"Eigenschappen erf je via DNA."},{"v":"Wat is de kleinste bouwsteen van een organisme?","o":["Een orgaan","Een cel","Een weefsel","Een chromosoom"],"c":1,"d":1,"u":"De cel is de kleinste bouwsteen van een organisme.","uo":["Een orgaan is uit veel cellen opgebouwd.","Klopt: de cel is de kleinste bouwsteen.","Een weefsel is een groep cellen.","Een chromosoom zit ín een cel."],"uh":"Cel = kleinste bouwsteen."},{"v":"Het hart en de bloedvaten werken samen om bloed rond te pompen. Samen vormen ze...","o":["een weefsel","een orgaan","een orgaanstelsel","een cel"],"c":2,"d":2,"u":"Organen die samen één functie uitvoeren vormen een orgaanstelsel.","uo":["Een weefsel is één soort cellen.","Een orgaan is één structuur, zoals het hart.","Klopt: samenwerkende organen vormen een orgaanstelsel.","Een cel is de kleinste bouwsteen."],"uh":"Orgaanstelsel = samenwerkende organen."},{"v":"Hoe heet de vloeistof in de cel waarin de onderdelen liggen?","o":["De celkern","De celwand","De vacuole","Het cytoplasma"],"c":3,"d":2,"u":"Het cytoplasma is de vloeistof in de cel waarin de onderdelen zweven.","uo":["De celkern bevat het DNA.","De celwand zit alleen bij planten.","De vacuole is een vochtblaas.","Klopt: het cytoplasma is de celvloeistof."],"uh":"Cytoplasma = vloeistof in de cel."},{"v":"Een grote vacuole vol vocht houdt een plant stevig. Bij welke cel hoort een grote vacuole?","o":["Een plantencel","Een dierlijke cel","Een bacterie","Een rode bloedcel"],"c":0,"d":3,"u":"Een grote vacuole komt voor in plantencellen.","uo":["Klopt: de vacuole hoort bij de plantencel.","Dierlijke cellen hebben geen grote vacuole.","Een bacterie is heel anders gebouwd.","Een rode bloedcel is een dierlijke cel."],"uh":"Vacuole = plantencel."},{"v":"Wat is de functie van het DNA in een cel?","o":["De cel stevig maken","De erfelijke informatie bevatten","Vocht opslaan","Zuurstof vervoeren"],"c":1,"d":2,"u":"Het DNA bevat de erfelijke informatie van het organisme.","uo":["Stevigheid komt van de celwand.","Klopt: DNA bevat de erfelijke informatie.","Vocht slaat de vacuole op.","Zuurstof vervoeren doen rode bloedcellen."],"uh":"DNA = erfelijke informatie."},{"v":"Bij een kruising is 3 op de 4 nakomelingen rood en 1 op de 4 wit. Wat weet je over de kleur rood?","o":["Rood is recessief","Rood en wit zijn even sterk","Rood is dominant","Kleur is niet erfelijk"],"c":2,"d":3,"u":"De verhouding 3 op 1 hoort bij een dominante eigenschap (rood).","uo":["Als rood recessief was, zou juist wit vaker voorkomen.","Dan zou je geen 3 op 1 zien.","Klopt: de verhouding 3 op 1 wijst op dominant rood.","Kleur wordt juist wél geërfd."],"uh":"3 op 1: de meerderheid is dominant."},{"v":"Welke van deze is een voorbeeld van een weefsel?","o":["Het hart","Het bloedvatenstelsel","Een levercel","Spierweefsel"],"c":3,"d":2,"u":"Spierweefsel bestaat uit cellen met dezelfde vorm en functie: een weefsel.","uo":["Het hart is een orgaan.","Het bloedvatenstelsel is een orgaanstelsel.","Een levercel is één cel.","Klopt: spierweefsel is een weefsel."],"uh":"Weefsel = groep gelijke cellen."},{"v":"Twee planten met hetzelfde genotype: de ene staat in de zon en groeit groter. Wat bepaalt dit verschil?","o":["De omgeving","Alleen het genotype","Het aantal chromosomen","Het celmembraan"],"c":0,"d":3,"u":"Het fenotype ontstaat uit het genotype én invloeden van de omgeving.","uo":["Klopt: de omgeving (zon) maakt het verschil.","Het genotype is juist gelijk.","Het aantal chromosomen is gelijk.","Het celmembraan speelt hier geen rol."],"uh":"Fenotype = genotype + omgeving."}],"begrippen":[{"t":"Cel","d":"de kleinste bouwsteen van een organisme"},{"t":"Weefsel","d":"een groep cellen met dezelfde vorm en functie"},{"t":"Orgaan","d":"een structuur van meerdere weefsels met een eigen taak"},{"t":"Orgaanstelsel","d":"organen die samen één functie uitvoeren"},{"t":"Celmembraan","d":"het dunne laagje dat de cel omsluit en stoffen doorlaat"},{"t":"Celkern","d":"het celonderdeel waarin het DNA ligt"},{"t":"Cytoplasma","d":"de vloeistof in de cel waarin de onderdelen liggen"},{"t":"Celwand","d":"de stevige buitenlaag om een plantencel"},{"t":"Bladgroenkorrel","d":"plantencelonderdeel dat de fotosynthese uitvoert"},{"t":"Vacuole","d":"een grote blaas met vocht in een plantencel"},{"t":"Chromosoom","d":"een streng van sterk opgerold DNA in de celkern"},{"t":"DNA","d":"de stof met de erfelijke informatie"},{"t":"Gen","d":"een stukje DNA met de code voor één eigenschap"},{"t":"Genotype","d":"de erfelijke aanleg (de genen) van een organisme"},{"t":"Fenotype","d":"de waarneembare eigenschappen van een organisme"},{"t":"Dominant allel","d":"een allel dat het fenotype al bepaalt als het aanwezig is"},{"t":"Recessief allel","d":"een allel dat alleen tot uiting komt bij twee exemplaren"},{"t":"Natuurlijke selectie","d":"het beter overleven en voortplanten van best aangepaste individuen"}],"sam":"<div class=\"sam-intro\">Alle levende wezens bestaan uit <strong>cellen</strong>. In dit domein leer je hoe cellen zijn opgebouwd, waarin een plantencel verschilt van een dierlijke cel, en hoe eigenschappen via <strong>DNA</strong> worden doorgegeven bij een <strong>monohybride kruising</strong>.</div><div class=\"sam-head\">1. Van cel tot organisme</div><p>De <strong>cel</strong> is de kleinste bouwsteen van een organisme. Cellen met dezelfde vorm en functie vormen samen een <strong>weefsel</strong> (bijvoorbeeld spierweefsel). Meerdere weefsels die samen een taak uitvoeren vormen een <strong>orgaan</strong>, zoals het hart. Organen die samenwerken aan één functie vormen een <strong>orgaanstelsel</strong>, zoals het bloedvatenstelsel.</p><p>Deze volgorde van klein naar groot (cel → weefsel → orgaan → orgaanstelsel → organisme) heet de organisatie van het lichaam. Elke laag is opgebouwd uit de laag eronder.</p><div class=\"sam-head\">2. De bouw van een cel</div><p>Elke cel wordt omsloten door een <strong>celmembraan</strong> dat bepaalt welke stoffen erin en eruit gaan. In de <strong>celkern</strong> ligt het <strong>DNA</strong>. De rest van de cel is gevuld met <strong>cytoplasma</strong>, de vloeistof waarin de celonderdelen liggen.</p><p>Een plantencel heeft drie extra onderdelen die een dierlijke cel niet heeft: een stevige <strong>celwand</strong>, <strong>bladgroenkorrels</strong> voor de fotosynthese en een grote <strong>vacuole</strong> met vocht.</p><div class=\"sam-head\">3. DNA, genen en chromosomen</div><p>Het <strong>DNA</strong> bevat alle erfelijke informatie. Een klein stukje DNA met de code voor één eigenschap heet een <strong>gen</strong>. Als DNA sterk wordt opgerold, vormt het een <strong>chromosoom</strong>; die zijn zichtbaar bij een celdeling.</p><p>Het <strong>genotype</strong> is de erfelijke aanleg (alle genen), het <strong>fenotype</strong> is wat je daarvan ziet: de waarneembare eigenschappen. Het fenotype ontstaat uit het genotype én invloeden van de omgeving.</p><div class=\"sam-head\">4. Kruisingen en overerving</div><p>Van elk gen heb je twee versies (allelen), één van elke ouder. Een <strong>dominant allel</strong> bepaalt de eigenschap al als het één keer aanwezig is; een <strong>recessief allel</strong> komt alleen tot uiting als beide allelen recessief zijn. Bij een <strong>monohybride kruising</strong> volg je één eigenschap.</p><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Kruis twee planten met genotype Aa. A (rood) is dominant over a (wit). Welke kleurverhouding krijg je?</div><ol class=\"sam-worked-steps\"><li>Zet de allelen in een kruisingsschema: Aa × Aa.</li><li>De mogelijke combinaties zijn AA, Aa, Aa en aa.</li><li>AA en Aa geven rood, aa geeft wit.</li></ol><div class=\"sam-worked-ans\">✅ De verhouding is 3 rood : 1 wit.</div></div><div class=\"sam-head\">5. Natuurlijke selectie</div><p>Individuen binnen een soort verschillen van elkaar. Bij <strong>natuurlijke selectie</strong> overleven en planten de individuen zich voort die het best zijn aangepast aan hun omgeving. Zo geven zij hun gunstige eigenschappen door en verandert een soort langzaam.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cel</div><div class=\"sam-definitie-body\">de kleinste bouwsteen van een organisme.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Weefsel</div><div class=\"sam-definitie-body\">een groep cellen met dezelfde vorm en functie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Orgaan</div><div class=\"sam-definitie-body\">een structuur van meerdere weefsels met een eigen taak.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Orgaanstelsel</div><div class=\"sam-definitie-body\">organen die samen één functie uitvoeren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Celmembraan</div><div class=\"sam-definitie-body\">het dunne laagje dat de cel omsluit en stoffen doorlaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Celkern</div><div class=\"sam-definitie-body\">het celonderdeel waarin het DNA ligt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cytoplasma</div><div class=\"sam-definitie-body\">de vloeistof in de cel waarin de onderdelen liggen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Celwand</div><div class=\"sam-definitie-body\">de stevige buitenlaag om een plantencel.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bladgroenkorrel</div><div class=\"sam-definitie-body\">plantencelonderdeel dat de fotosynthese uitvoert.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vacuole</div><div class=\"sam-definitie-body\">een grote blaas met vocht in een plantencel.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Chromosoom</div><div class=\"sam-definitie-body\">een streng van sterk opgerold DNA in de celkern.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">DNA</div><div class=\"sam-definitie-body\">de stof met de erfelijke informatie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gen</div><div class=\"sam-definitie-body\">een stukje DNA met de code voor één eigenschap.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Genotype</div><div class=\"sam-definitie-body\">de erfelijke aanleg (de genen) van een organisme.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Fenotype</div><div class=\"sam-definitie-body\">de waarneembare eigenschappen van een organisme.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Dominant allel</div><div class=\"sam-definitie-body\">een allel dat het fenotype al bepaalt als het aanwezig is.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Recessief allel</div><div class=\"sam-definitie-body\">een allel dat alleen tot uiting komt bij twee exemplaren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Natuurlijke selectie</div><div class=\"sam-definitie-body\">het beter overleven en voortplanten van best aangepaste individuen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Cel»</b> is kleinste bouwsteen, terwijl <b>«Weefsel»</b> groep gelijke cellen is. <b>«Orgaan»</b> is meerdere weefsels met een taak, terwijl <b>«Weefsel»</b> groep gelijke cellen is. <b>«Orgaanstelsel»</b> is samenwerkende organen, terwijl <b>«Orgaan»</b> meerdere weefsels met een taak is. <b>«Celmembraan»</b> is omhulsel van de cel, terwijl <b>«Celwand»</b> stevige laag bij planten is.</div>"},"B":{"sv":[{"v":"Welke huidlaag ligt aan de buitenkant?","o":["De diepe lederhuidlaag","De opperhuid","Het onderhuids vetweefsel","De vochtige celkern"],"c":1,"d":2,"u":"De opperhuid ligt bovenop.","uo":["De lederhuid ligt juist dieper.","Klopt: de opperhuid ligt bovenop.","Dat is de vetlaag nog dieper.","De celkern hoort bij een cel."],"uh":"De opperhuid ligt bovenop."},{"v":"Waar zitten de zenuwen en bloedvaten van de huid?","o":["In de dode opperhuidlaag","In het haar op je huid","In de lederhuid","In de rand van je nagel"],"c":2,"d":2,"u":"De lederhuid bevat zenuwen en bloedvaten.","uo":["De opperhuid is de dode buitenlaag.","Haar is geen huidlaag.","Klopt: de lederhuid bevat zenuwen en bloedvaten.","Een nagel is geen huidlaag."],"uh":"In de lederhuid: De lederhuid bevat zenuwen en bloedvaten."},{"v":"Als je het warm hebt ga je zweten. Welke klier doet dat?","o":["De zweetklier","De talgklier voor huidvet","De celkern in de cel","De beschermende opperhuid"],"c":0,"d":3,"u":"De zweetklier koelt je af.","uo":["Klopt: de zweetklier koelt je af.","De talgklier geeft juist huidvet af.","De celkern hoort bij een cel.","De opperhuid is een laag, geen klier."],"uh":"De zweetklier koelt je af."},{"v":"Wat is de belangrijkste functie van de huid?","o":["Het bloed rondpompen","Het voedsel verteren","Het zuurstof opnemen","Beschermen"],"c":3,"d":2,"u":"De huid beschermt het lichaam.","uo":["Bloed rondpompen doet het hart.","Verteren gebeurt in de darmen.","Zuurstof nemen de longen op.","Klopt: de huid beschermt het lichaam."],"uh":"Beschermen: De huid beschermt het lichaam."},{"v":"Welke functie heeft het skelet, naast bescherming?","o":["Het bloed zuiveren","Steun geven","Het zuurstof vervoeren","Het voedsel opslaan"],"c":1,"d":2,"u":"Het skelet geeft steun en vorm.","uo":["Bloed zuiveren doen de nieren.","Klopt: het skelet geeft steun en vorm.","Zuurstof vervoeren doet het bloed.","Voedsel opslaan is geen skeletfunctie."],"uh":"Steun geven: Het skelet geeft steun en vorm."},{"v":"Het oor en de neus zijn stevig maar buigzaam. Wat is dat?","o":["Hard en stevig bot","Een trekkende spier","Kraakbeen","De beschermende huid"],"c":2,"d":3,"u":"Kraakbeen is stevig en buigzaam.","uo":["Bot is hard en niet buigzaam.","Een spier kan samentrekken.","Klopt: kraakbeen is stevig en buigzaam.","De huid is de bedekking."],"uh":"Kraakbeen is stevig en buigzaam."},{"v":"Welke laag onder de huid houdt de warmte vast?","o":["De dunne dode opperhuid","De vetlaag","Een gladde talgklier","De buitenste hoornlaag"],"c":1,"d":2,"u":"De vetlaag houdt warmte vast.","uo":["De opperhuid is dun en dood.","Klopt: de vetlaag houdt warmte vast.","Een talgklier geeft vet af.","De hoornlaag is de buitenkant."],"uh":"De vetlaag houdt warmte vast."},{"v":"Waardoor blijft je huid soepel?","o":["Door afkoelend zweet","Door voedend bloed","Door stevig kraakbeen","Door talg"],"c":3,"d":2,"u":"Talg houdt de huid soepel.","uo":["Zweet koelt je juist af.","Bloed voedt de huid.","Kraakbeen zit in oor en neus.","Klopt: talg houdt de huid soepel."],"uh":"Door talg: Talg houdt de huid soepel."},{"v":"Alle botten samen noem je het...","o":["spierstelsel","skelet","steunweefsel","zenuwstelsel"],"c":1,"d":1,"u":"Alle botten samen zijn het skelet.","uo":["Het spierstelsel bestaat uit spieren.","Klopt: alle botten samen zijn het skelet.","Kraakbeen is steunweefsel.","Het zenuwstelsel geeft prikkels door."],"uh":"skelet: Alle botten samen zijn het skelet."},{"v":"Wat doet een talgklier?","o":["Zweet afgeven en koelen","Bloed door het lichaam pompen","Huidvet afgeven","Nieuwe botten aanmaken"],"c":2,"d":2,"u":"De talgklier geeft huidvet af.","uo":["Zweet afgeven doet de zweetklier.","Bloed pompen doet het hart.","Klopt: de talgklier geeft huidvet af.","Botten maakt het beenmerg."],"uh":"Huidvet afgeven: De talgklier geeft huidvet af."},{"v":"Wat is kraakbeen?","o":["Buigzaam steunweefsel","Een samentrekkende spier","Een bedekkende huidlaag","Een vervoerend bloedvat"],"c":0,"d":1,"u":"Kraakbeen is buigzaam steunweefsel.","uo":["Klopt: kraakbeen is buigzaam steunweefsel.","Een spier kan samentrekken.","Een huidlaag beschermt.","Een bloedvat vervoert bloed."],"uh":"Buigzaam steunweefsel: Kraakbeen is buigzaam steunweefsel."},{"v":"Bij een schaafwond raakt vooral de buitenste laag stuk. Welke?","o":["De diepe lederhuid","Het onderhuids bindweefsel","Een hard bot","De opperhuid"],"c":3,"d":3,"u":"De opperhuid is de buitenste laag.","uo":["De lederhuid ligt dieper.","Het bindweefsel ligt onderop.","Een bot zit veel dieper.","Klopt: de opperhuid is de buitenste laag."],"uh":"De opperhuid is de buitenste laag."},{"v":"Wat beschermt je organen tegen stoten van buiten?","o":["De koelende zweetklier","Het skelet","Het vloeibare cytoplasma","De grote vacuole"],"c":1,"d":2,"u":"Het skelet beschermt de organen.","uo":["De zweetklier koelt af.","Klopt: het skelet beschermt de organen.","Cytoplasma zit in een cel.","De vacuole hoort bij een plantencel."],"uh":"Het skelet beschermt de organen."},{"v":"Waartegen beschermt de huid vooral?","o":["Tegen te veel eigen bloed","Tegen te veel botten","Tegen ziekteverwekkers","Tegen je eigen spieren"],"c":2,"d":2,"u":"Tegen ziekteverwekkers en uitdroging.","uo":["Bloed hoort juist in het lichaam.","Botten horen bij het skelet.","Klopt: tegen ziekteverwekkers en uitdroging.","Spieren horen bij beweging."],"uh":"Tegen ziekteverwekkers en uitdroging."},{"v":"Welke twee taken heeft het skelet vooral?","o":["Voedsel verteren en ademhalen","Steun en bescherming","Zien en horen met zintuigen","Bloed pompen en koelen"],"c":1,"d":2,"u":"Steun geven en beschermen.","uo":["Dat doen darmen en longen.","Klopt: steun geven en beschermen.","Dat doen de zintuigen.","Dat doen hart en huid."],"uh":"Steun en bescherming: Steun geven en beschermen."},{"v":"Spierweefsel bestaat uit cellen die op elkaar lijken. Wat is het?","o":["Een groep samenwerkende organen","Een enkele losse lichaamscel","Een hard stuk bot","Een weefsel"],"c":3,"d":2,"u":"Gelijke cellen vormen een weefsel.","uo":["Dat is een orgaanstelsel.","Het is niet één losse cel.","Een bot is iets anders.","Klopt: gelijke cellen vormen een weefsel."],"uh":"Een weefsel: Gelijke cellen vormen een weefsel."}],"begrippen":[{"t":"Huid","d":"het orgaan dat het lichaam bedekt en beschermt"},{"t":"Opperhuid","d":"de buitenste laag van de huid"},{"t":"Lederhuid","d":"de laag onder de opperhuid met zenuwen en bloedvaten"},{"t":"Onderhuids bindweefsel","d":"de vetlaag onder de lederhuid die warmte vasthoudt"},{"t":"Skelet","d":"alle botten samen die het lichaam steun en vorm geven"},{"t":"Bot","d":"een hard orgaan dat steun geeft en bloedcellen kan maken"},{"t":"Kraakbeen","d":"stevig maar buigzaam steunweefsel, bijvoorbeeld in het oor"},{"t":"Beschermende functie","d":"het afschermen van organen tegen schade van buiten"},{"t":"Steunfunctie","d":"het geven van stevigheid en vorm aan het lichaam"},{"t":"Talgklier","d":"huidklier die vet afgeeft en de huid soepel houdt"},{"t":"Zweetklier","d":"huidklier die zweet afgeeft en zo het lichaam koelt"},{"t":"Ziekteverwekker","d":"een micro-organisme dat een ziekte kan veroorzaken"}],"sam":"<div class=\"sam-intro\">Het lichaam heeft <strong>stevigheid</strong> en <strong>bescherming</strong> nodig. De <strong>huid</strong> houdt ziekteverwekkers en uitdroging tegen, en het <strong>skelet</strong> geeft steun en vorm.</div><div class=\"sam-head\">1. De huid beschermt</div><p>De <strong>huid</strong> is het grootste orgaan en beschermt tegen uitdroging, kou en ziekteverwekkers. Bovenop ligt de <strong>opperhuid</strong>, met daaronder de <strong>lederhuid</strong> vol zenuwen en bloedvaten, en daaronder het <strong>onderhuids bindweefsel</strong> met vet dat warmte vasthoudt.</p><p>In de huid zitten klieren: een <strong>talgklier</strong> geeft huidvet af dat de huid soepel houdt, en een <strong>zweetklier</strong> geeft zweet af waarmee het lichaam afkoelt.</p><div class=\"sam-head\">2. Steun en stevigheid</div><p>Het <strong>skelet</strong> geeft het lichaam vorm en steun en beschermt kwetsbare organen: de <strong>steunfunctie</strong> en de <strong>beschermende functie</strong>. Botten zijn hard, terwijl <strong>kraakbeen</strong> stevig maar buigzaam is, zoals in het oor en de neus.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Huid</div><div class=\"sam-definitie-body\">het orgaan dat het lichaam bedekt en beschermt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Opperhuid</div><div class=\"sam-definitie-body\">de buitenste laag van de huid.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lederhuid</div><div class=\"sam-definitie-body\">de laag onder de opperhuid met zenuwen en bloedvaten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Onderhuids bindweefsel</div><div class=\"sam-definitie-body\">de vetlaag onder de lederhuid die warmte vasthoudt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Skelet</div><div class=\"sam-definitie-body\">alle botten samen die het lichaam steun en vorm geven.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bot</div><div class=\"sam-definitie-body\">een hard orgaan dat steun geeft en bloedcellen kan maken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kraakbeen</div><div class=\"sam-definitie-body\">stevig maar buigzaam steunweefsel, bijvoorbeeld in het oor.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Beschermende functie</div><div class=\"sam-definitie-body\">het afschermen van organen tegen schade van buiten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Steunfunctie</div><div class=\"sam-definitie-body\">het geven van stevigheid en vorm aan het lichaam.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Talgklier</div><div class=\"sam-definitie-body\">huidklier die vet afgeeft en de huid soepel houdt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zweetklier</div><div class=\"sam-definitie-body\">huidklier die zweet afgeeft en zo het lichaam koelt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ziekteverwekker</div><div class=\"sam-definitie-body\">een micro-organisme dat een ziekte kan veroorzaken.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Huid»</b> is beschermende bedekking, terwijl <b>«Opperhuid»</b> buitenste huidlaag is. <b>«Opperhuid»</b> is buitenste huidlaag, terwijl <b>«Lederhuid»</b> laag onder de opperhuid is. <b>«Onderhuids bindweefsel»</b> is vetlaag, houdt warmte vast, terwijl <b>«Lederhuid»</b> laag onder de opperhuid is. <b>«Skelet»</b> is alle botten samen, terwijl <b>«Bot»</b> hard steunorgaan is.</div>"},"C":{"sv":[{"v":"Wat maakt een plant met fotosynthese?","o":["Zuurstof en afval","Alleen schoon water","Glucose (suiker)","Stikstof uit de bodem"],"c":2,"d":2,"u":"Een plant maakt glucose.","uo":["Zuurstof komt vrij, maar is niet het hoofdproduct.","Water is een grondstof, geen product.","Klopt: een plant maakt glucose.","Stikstof komt uit de bodem."],"uh":"Glucose (suiker): Een plant maakt glucose."},{"v":"Wat is een producent in een voedselketen?","o":["Een plant","Een vleesetend dier","Een afbrekende schimmel","Een grazend hert"],"c":0,"d":1,"u":"Een plant maakt zelf voedsel.","uo":["Klopt: een plant maakt zelf voedsel.","Dat is een consument.","Dat is een reducent.","Dat is een herbivoor."],"uh":"Een plant maakt zelf voedsel."},{"v":"Een schimmel breekt dode bladeren af. Wat is de schimmel?","o":["Een producent","Een reducent","Een herbivoor","Een carnivoor"],"c":1,"d":3,"u":"Een reducent breekt dood materiaal af.","uo":["Een producent maakt zelf voedsel.","Klopt: een reducent breekt dood materiaal af.","Een herbivoor eet planten.","Een carnivoor eet dieren."],"uh":"Een reducent breekt dood materiaal af."},{"v":"Een koe eet alleen gras. Wat voor eter is een koe?","o":["Een carnivoor","Een reducent","Een producent","Een herbivoor"],"c":3,"d":2,"u":"Een herbivoor eet planten.","uo":["Een carnivoor eet vlees.","Een reducent breekt af.","Een producent maakt voedsel.","Klopt: een herbivoor eet planten."],"uh":"Een herbivoor eet planten."},{"v":"Wat gebeurt er in een voedselweb?","o":["Eén rechte eetketen","Alleen planten groeien","Meerdere ketens zijn verbonden","Stoffen verdwijnen"],"c":2,"d":2,"u":"Meerdere ketens zijn met elkaar verbonden.","uo":["Dat is een voedselketen.","Een web bevat ook dieren.","Klopt: meerdere ketens zijn met elkaar verbonden.","Stoffen gaan juist rond."],"uh":"Meerdere ketens zijn met elkaar verbonden."},{"v":"Wat doen reducenten met dode resten?","o":["Ze breken ze af","Ze eten levende dieren","Ze maken er licht van","Ze pompen bloed rond"],"c":0,"d":1,"u":"Reducenten breken dode resten af.","uo":["Klopt: reducenten breken dode resten af.","Ze eten geen levende dieren.","Ze maken geen licht.","Bloed pompen doet een hart."],"uh":"Ze breken ze af: Reducenten breken dode resten af."},{"v":"Wat heeft een plant nodig voor fotosynthese?","o":["Zuurstof uit de lucht","Licht, water en CO2","Suiker als brandstof","Vlees en eiwitten"],"c":1,"d":2,"u":"Licht, water en koolstofdioxide.","uo":["Zuurstof komt juist vrij.","Klopt: licht, water en koolstofdioxide.","Suiker is het product.","Planten eten geen vlees."],"uh":"Licht, water en koolstofdioxide."},{"v":"In welke kringloop gaat koolstof rond?","o":["De waterkringloop","De stikstofkringloop","De voedselketen","De koolstofkringloop"],"c":3,"d":2,"u":"Koolstof in de koolstofkringloop.","uo":["Water gaat rond in de waterkringloop.","Stikstof in de stikstofkringloop.","Een keten is geen kringloop.","Klopt: koolstof in de koolstofkringloop."],"uh":"De koolstofkringloop: Koolstof in de koolstofkringloop."},{"v":"Een dier eet zowel planten als andere dieren. Wat is het?","o":["Een herbivoor","Een producent","Een omnivoor","Een reducent"],"c":2,"d":3,"u":"Een omnivoor eet allebei.","uo":["Een herbivoor eet alleen planten.","Een producent maakt voedsel.","Klopt: een omnivoor eet allebei.","Een reducent breekt af."],"uh":"Een omnivoor eet allebei."},{"v":"Waarom noem je planten producenten?","o":["Ze maken zelf hun voedsel","Ze eten andere dieren","Ze breken resten af","Ze pompen bloed rond"],"c":0,"d":2,"u":"Planten maken zelf voedsel.","uo":["Klopt: planten maken zelf voedsel.","Dat doen consumenten.","Dat doen reducenten.","Bloed pompen doet een hart."],"uh":"Ze maken zelf hun voedsel: Planten maken zelf voedsel."},{"v":"Wat gebeurt er bij fotosynthese?","o":["Suiker wordt juist verbrand","Er wordt suiker gemaakt","Er wordt bloed rondgepompt","Water verdampt in de lucht"],"c":1,"d":2,"u":"Er wordt suiker gemaakt.","uo":["Verbranden is het tegenovergestelde.","Klopt: er wordt suiker gemaakt.","Bloed pompen doet een hart.","Dat is verdamping."],"uh":"Er wordt suiker gemaakt."},{"v":"Wat is een reducent, bijvoorbeeld?","o":["Een grasetend konijn","Een groene plant","Een jagende vos","Een schimmel"],"c":3,"d":3,"u":"Een schimmel is een reducent.","uo":["Dat is een herbivoor.","Dat is een producent.","Dat is een carnivoor.","Klopt: een schimmel is een reducent."],"uh":"Een schimmel is een reducent."},{"v":"Waardoor blijven stoffen in een ecosysteem rondgaan?","o":["Door alleen de planten","Door alleen de dieren","Door kringlopen","Doordat ze verdwijnen"],"c":2,"d":2,"u":"Door kringlopen gaan stoffen rond.","uo":["Planten alleen is niet genoeg.","Dieren alleen is niet genoeg.","Klopt: door kringlopen gaan stoffen rond.","Stoffen verdwijnen niet."],"uh":"Door kringlopen gaan stoffen rond."},{"v":"Wat is een ecosysteem?","o":["Organismen met hun omgeving","Alleen de dieren in een gebied","Alleen de groene planten","Alleen de kale bodem"],"c":0,"d":1,"u":"Organismen samen met hun omgeving.","uo":["Klopt: organismen samen met hun omgeving.","Dieren zijn maar een deel.","Planten zijn maar een deel.","De bodem is maar een deel."],"uh":"Organismen samen met hun omgeving."},{"v":"Een vos eet konijnen. Wat voor eter is de vos?","o":["Een herbivoor","Een carnivoor","Een producent","Een reducent"],"c":1,"d":2,"u":"Een carnivoor eet dieren.","uo":["Een herbivoor eet planten.","Klopt: een carnivoor eet dieren.","Een producent maakt voedsel.","Een reducent breekt af."],"uh":"Een carnivoor eet dieren."},{"v":"Welke stof komt vrij bij fotosynthese?","o":["Koolstofdioxide","Stikstof","Suiker","Zuurstof"],"c":3,"d":2,"u":"Er komt zuurstof vrij.","uo":["CO2 is juist een grondstof.","Stikstof speelt hier geen rol.","Suiker blijft in de plant.","Klopt: er komt zuurstof vrij."],"uh":"Zuurstof: Er komt zuurstof vrij."}],"begrippen":[{"t":"Voedselketen","d":"een reeks organismen die elkaar opeten, van producent naar consument"},{"t":"Voedselweb","d":"meerdere voedselketens die met elkaar verbonden zijn"},{"t":"Producent","d":"een organisme dat zelf voedsel maakt, meestal een plant"},{"t":"Consument","d":"een organisme dat andere organismen eet"},{"t":"Reducent","d":"een organisme dat dood materiaal afbreekt, zoals een schimmel"},{"t":"Fotosynthese","d":"het maken van glucose uit koolstofdioxide en water met licht"},{"t":"Verbranding","d":"het vrijmaken van energie uit voedingsstoffen met zuurstof"},{"t":"Koolstofkringloop","d":"de kringloop waarin koolstof tussen organismen en lucht rondgaat"},{"t":"Stikstofkringloop","d":"de kringloop waarin stikstof via bacteriën en planten rondgaat"},{"t":"Herbivoor","d":"een dier dat alleen planten eet"},{"t":"Carnivoor","d":"een dier dat andere dieren eet"},{"t":"Omnivoor","d":"een dier dat zowel planten als dieren eet"},{"t":"Ecosysteem","d":"een leefgebied met alle organismen en hun omgeving samen"}],"sam":"<div class=\"sam-intro\">In een ecosysteem hangen organismen met elkaar samen. <strong>Producenten</strong> maken met <strong>fotosynthese</strong> zelf voedsel, <strong>consumenten</strong> eten anderen en <strong>reducenten</strong> breken dood materiaal af. Zo blijven stoffen in een <strong>kringloop</strong> rondgaan.</div><div class=\"sam-head\">1. Voedselketens en voedselwebben</div><p>Een <strong>voedselketen</strong> laat zien wie wie eet, in een rechte lijn: van <strong>producent</strong> naar <strong>consument</strong>. In werkelijkheid eten veel dieren van meerdere soorten; als je die ketens met elkaar verbindt, krijg je een <strong>voedselweb</strong>.</p><p>Je onderscheidt eters naar hun voedsel: een <strong>herbivoor</strong> eet planten, een <strong>carnivoor</strong> eet dieren en een <strong>omnivoor</strong> eet beide.</p><div class=\"sam-head\">2. Producenten, consumenten en reducenten</div><p><strong>Producenten</strong> (groene planten) maken hun eigen voedsel met <strong>fotosynthese</strong>. <strong>Consumenten</strong> kunnen dat niet en eten daarom andere organismen. <strong>Reducenten</strong>, zoals schimmels en bacteriën, breken dode resten af tot stoffen die planten weer kunnen gebruiken.</p><div class=\"sam-head\">3. Kringlopen</div><p>Doordat producenten, consumenten en reducenten samenwerken, blijven stoffen rondgaan. In de <strong>koolstofkringloop</strong> gaat koolstof via fotosynthese en verbranding tussen lucht en organismen rond. In de <strong>stikstofkringloop</strong> zorgen bacteriën dat stikstof beschikbaar blijft voor planten.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Voedselketen</div><div class=\"sam-definitie-body\">een reeks organismen die elkaar opeten, van producent naar consument.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Voedselweb</div><div class=\"sam-definitie-body\">meerdere voedselketens die met elkaar verbonden zijn.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Producent</div><div class=\"sam-definitie-body\">een organisme dat zelf voedsel maakt, meestal een plant.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Consument</div><div class=\"sam-definitie-body\">een organisme dat andere organismen eet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Reducent</div><div class=\"sam-definitie-body\">een organisme dat dood materiaal afbreekt, zoals een schimmel.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Fotosynthese</div><div class=\"sam-definitie-body\">het maken van glucose uit koolstofdioxide en water met licht.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verbranding</div><div class=\"sam-definitie-body\">het vrijmaken van energie uit voedingsstoffen met zuurstof.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Koolstofkringloop</div><div class=\"sam-definitie-body\">de kringloop waarin koolstof tussen organismen en lucht rondgaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stikstofkringloop</div><div class=\"sam-definitie-body\">de kringloop waarin stikstof via bacteriën en planten rondgaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Herbivoor</div><div class=\"sam-definitie-body\">een dier dat alleen planten eet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Carnivoor</div><div class=\"sam-definitie-body\">een dier dat andere dieren eet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Omnivoor</div><div class=\"sam-definitie-body\">een dier dat zowel planten als dieren eet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ecosysteem</div><div class=\"sam-definitie-body\">een leefgebied met alle organismen en hun omgeving samen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Voedselketen»</b> is wie eet wie, in een lijn, terwijl <b>«Voedselweb»</b> verbonden voedselketens is. <b>«Producent»</b> is maakt zelf voedsel, terwijl <b>«Consument»</b> eet andere organismen is. <b>«Reducent»</b> is breekt dood materiaal af, terwijl <b>«Producent»</b> maakt zelf voedsel is. <b>«Fotosynthese»</b> is suiker maken met licht, terwijl <b>«Verbranding»</b> energie vrijmaken met zuurstof is.</div>"},"D":{"sv":[{"v":"Wat hoort bij milieuvervuiling?","o":["Bomen planten langs de weg","Schadelijke stoffen lozen","Afval netjes scheiden","Zonnepanelen plaatsen"],"c":1,"d":2,"u":"Schadelijke stoffen in de omgeving brengen.","uo":["Bomen planten helpt juist.","Klopt: schadelijke stoffen in de omgeving brengen.","Scheiden is juist goed.","Zonnepanelen zijn schoon."],"uh":"Schadelijke stoffen in de omgeving brengen."},{"v":"Waardoor warmt de aarde op?","o":["Door recycling","Door meer bomen","Door het broeikaseffect","Door schone lucht"],"c":2,"d":2,"u":"Door het broeikaseffect.","uo":["Recycling helpt juist.","Bomen nemen CO2 op.","Klopt: door het broeikaseffect.","Schone lucht warmt niet op."],"uh":"Door het broeikaseffect."},{"v":"Welke energiebron raakt op?","o":["Zonne-energie","Windenergie","Waterkracht","Aardgas"],"c":3,"d":3,"u":"Aardgas is een fossiele brandstof.","uo":["De zon raakt niet op.","Wind raakt niet op.","Water raakt niet op.","Klopt: aardgas is een fossiele brandstof."],"uh":"Aardgas is een fossiele brandstof."},{"v":"Wat is duurzaam gedrag?","o":["Grondstoffen hergebruiken","Alles meteen weggooien","Veel benzine blijven verbruiken","Oude bomen omkappen"],"c":0,"d":2,"u":"Hergebruiken is duurzaam.","uo":["Klopt: hergebruiken is duurzaam.","Weggooien is niet duurzaam.","Benzine vervuilt.","Bomen kappen schaadt de natuur."],"uh":"Grondstoffen hergebruiken: Hergebruiken is duurzaam."},{"v":"Wat is een broeikasgas?","o":["Zuurstof","Koolstofdioxide","Stikstof","Waterstof"],"c":1,"d":1,"u":"CO2 houdt warmte vast.","uo":["Zuurstof is geen broeikasgas.","Klopt: CO2 houdt warmte vast.","Stikstof is geen broeikasgas.","Waterstof speelt hier geen rol."],"uh":"Koolstofdioxide: CO2 houdt warmte vast."},{"v":"Wat gebeurt er bij recycling?","o":["Afval wordt verbrand","Afval blijft liggen","Afval wordt hergebruikt","Afval wordt begraven"],"c":2,"d":2,"u":"Afval wordt een nieuwe grondstof.","uo":["Verbranden is geen recycling.","Blijven liggen helpt niet.","Klopt: afval wordt een nieuwe grondstof.","Begraven is geen hergebruik."],"uh":"Afval wordt een nieuwe grondstof."},{"v":"Welke energiebron is duurzaam?","o":["Aardolie","Steenkool","Aardgas","Windenergie"],"c":3,"d":3,"u":"Wind raakt niet op.","uo":["Aardolie raakt op.","Steenkool raakt op.","Aardgas raakt op.","Klopt: wind raakt niet op."],"uh":"Windenergie: Wind raakt niet op."},{"v":"Wat is kringloopdenken?","o":["Grondstoffen opnieuw gebruiken","Steeds nieuwe grondstoffen kopen","Alles verbranden","Water verspillen"],"c":0,"d":2,"u":"Grondstoffen opnieuw gebruiken.","uo":["Klopt: grondstoffen opnieuw gebruiken.","Nieuw kopen is het tegenovergestelde.","Verbranden is geen kringloop.","Verspillen is niet duurzaam."],"uh":"Grondstoffen opnieuw gebruiken."},{"v":"Waarom is het broeikaseffect een probleem?","o":["De aarde koelt af","De aarde warmt op","Er komt meer zuurstof","Er groeien meer bomen"],"c":1,"d":2,"u":"De aarde warmt op.","uo":["De aarde koelt niet af.","Klopt: de aarde warmt op.","Zuurstof is niet het probleem.","Meer bomen zou juist helpen."],"uh":"De aarde warmt op."},{"v":"Wat is een fossiele brandstof?","o":["Zonlicht","Wind","Aardolie","Stromend water"],"c":2,"d":1,"u":"Aardolie is fossiel.","uo":["Zonlicht is duurzaam.","Wind is duurzaam.","Klopt: aardolie is fossiel.","Water is duurzaam."],"uh":"Aardolie is fossiel."},{"v":"Wat betekent duurzaamheid?","o":["Alles snel opmaken","Zoveel mogelijk kopen","Grondstoffen uitputten","Genoeg overhouden voor later"],"c":3,"d":2,"u":"Ook voor de toekomst genoeg overhouden.","uo":["Opmaken is niet duurzaam.","Veel kopen is niet duurzaam.","Uitputten is niet duurzaam.","Klopt: ook voor de toekomst genoeg overhouden."],"uh":"Genoeg overhouden voor later: Ook voor de toekomst genoeg overhouden."},{"v":"Wat helpt tegen het broeikaseffect?","o":["Minder fossiele brandstof gebruiken","Steeds meer kolen verbranden","Veel meer met de auto rijden","Grote bossen kappen"],"c":0,"d":2,"u":"Minder fossiele brandstof gebruiken.","uo":["Klopt: minder fossiele brandstof gebruiken.","Kolen verergeren het.","Auto rijden stoot CO2 uit.","Bossen kappen verergert het."],"uh":"Minder fossiele brandstof gebruiken."},{"v":"Wat is fijnstof?","o":["Heel schone lucht","Kleine schadelijke deeltjes","Gewone zuurstof","Schoon regenwater"],"c":1,"d":1,"u":"Kleine schadelijke deeltjes in de lucht.","uo":["Fijnstof maakt de lucht juist vuil.","Klopt: kleine schadelijke deeltjes in de lucht.","Zuurstof is geen fijnstof.","Water is geen fijnstof."],"uh":"Kleine schadelijke deeltjes in de lucht."},{"v":"Wat is biodiversiteit?","o":["Eén enkele soort in een gebied","Helemaal geen leven","De verscheidenheid aan soorten","Alleen groene planten"],"c":2,"d":2,"u":"De rijkdom aan verschillende soorten.","uo":["Eén soort is juist weinig diversiteit.","Zonder leven is er geen diversiteit.","Klopt: de rijkdom aan verschillende soorten.","Alleen planten is te beperkt."],"uh":"De verscheidenheid aan soorten: De rijkdom aan verschillende soorten."},{"v":"Welke energiebron raakt niet op?","o":["Aardgas","Steenkool","Aardolie","Zonne-energie"],"c":3,"d":3,"u":"De zon raakt niet op.","uo":["Aardgas raakt op.","Steenkool raakt op.","Aardolie raakt op.","Klopt: de zon raakt niet op."],"uh":"Zonne-energie: De zon raakt niet op."},{"v":"Waarom is recycling goed voor het milieu?","o":["Er zijn minder grondstoffen nodig","Er ontstaat juist veel meer afval","Er wordt meer brandstof verstookt","Er komt meer vervuiling vrij"],"c":0,"d":2,"u":"Er zijn minder nieuwe grondstoffen nodig.","uo":["Klopt: er zijn minder nieuwe grondstoffen nodig.","Recycling geeft juist minder afval.","Recycling is geen verbranding.","Recycling vermindert vervuiling."],"uh":"Er zijn minder nieuwe grondstoffen nodig."}],"begrippen":[{"t":"Milieuvervuiling","d":"het toevoegen van schadelijke stoffen aan lucht, water of bodem"},{"t":"Broeikaseffect","d":"het opwarmen van de aarde door broeikasgassen in de lucht"},{"t":"Broeikasgas","d":"een gas zoals koolstofdioxide dat warmte vasthoudt"},{"t":"Duurzaamheid","d":"zo leven dat er ook voor de toekomst genoeg overblijft"},{"t":"Kringloopdenken","d":"grondstoffen steeds opnieuw gebruiken in plaats van weggooien"},{"t":"Recycling","d":"afval verwerken tot nieuwe grondstoffen of producten"},{"t":"Duurzame energie","d":"energie uit bronnen die niet opraken, zoals zon en wind"},{"t":"Fossiele brandstof","d":"brandstof uit resten van organismen, zoals olie en gas"},{"t":"Biodiversiteit","d":"de verscheidenheid aan soorten in een gebied"},{"t":"Afbreekbaar","d":"materiaal dat door reducenten wordt afgebroken"},{"t":"Fijnstof","d":"kleine zwevende deeltjes in de lucht die schadelijk zijn"},{"t":"Grondstof","d":"een natuurlijke stof waarvan je iets maakt"}],"sam":"<div class=\"sam-intro\">De mens gebruikt grondstoffen en veroorzaakt <strong>milieuvervuiling</strong>. Met <strong>duurzaamheid</strong> en <strong>kringloopdenken</strong> proberen we die invloed te verkleinen.</div><div class=\"sam-head\">1. Vervuiling en klimaat</div><p>Bij <strong>milieuvervuiling</strong> komen schadelijke stoffen in lucht, water of bodem. Door het verbranden van <strong>fossiele brandstoffen</strong> komen <strong>broeikasgassen</strong> vrij die warmte vasthouden: het <strong>broeikaseffect</strong>, waardoor de aarde opwarmt.</p><div class=\"sam-head\">2. Duurzaam met grondstoffen</div><p><strong>Duurzaamheid</strong> betekent zo leven dat er ook voor de toekomst genoeg overblijft. Bij <strong>kringloopdenken</strong> gebruik je grondstoffen steeds opnieuw in plaats van ze weg te gooien; <strong>recycling</strong> en <strong>duurzame energie</strong> horen daarbij. Zo blijft de <strong>biodiversiteit</strong> beter behouden.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Milieuvervuiling</div><div class=\"sam-definitie-body\">het toevoegen van schadelijke stoffen aan lucht, water of bodem.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Broeikaseffect</div><div class=\"sam-definitie-body\">het opwarmen van de aarde door broeikasgassen in de lucht.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Broeikasgas</div><div class=\"sam-definitie-body\">een gas zoals koolstofdioxide dat warmte vasthoudt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Duurzaamheid</div><div class=\"sam-definitie-body\">zo leven dat er ook voor de toekomst genoeg overblijft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kringloopdenken</div><div class=\"sam-definitie-body\">grondstoffen steeds opnieuw gebruiken in plaats van weggooien.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Recycling</div><div class=\"sam-definitie-body\">afval verwerken tot nieuwe grondstoffen of producten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Duurzame energie</div><div class=\"sam-definitie-body\">energie uit bronnen die niet opraken, zoals zon en wind.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Fossiele brandstof</div><div class=\"sam-definitie-body\">brandstof uit resten van organismen, zoals olie en gas.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Biodiversiteit</div><div class=\"sam-definitie-body\">de verscheidenheid aan soorten in een gebied.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Afbreekbaar</div><div class=\"sam-definitie-body\">materiaal dat door reducenten wordt afgebroken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Fijnstof</div><div class=\"sam-definitie-body\">kleine zwevende deeltjes in de lucht die schadelijk zijn.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Grondstof</div><div class=\"sam-definitie-body\">een natuurlijke stof waarvan je iets maakt.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Milieuvervuiling»</b> is schadelijke stoffen lozen, terwijl <b>«Broeikaseffect»</b> aarde warmt op is. <b>«Broeikasgas»</b> is gas dat warmte vasthoudt, terwijl <b>«Fijnstof»</b> schadelijke luchtdeeltjes is. <b>«Duurzaamheid»</b> is toekomstbestendig leven, terwijl <b>«Kringloopdenken»</b> grondstoffen hergebruiken is. <b>«Recycling»</b> is afval hergebruiken, terwijl <b>«Kringloopdenken»</b> grondstoffen hergebruiken is.</div>"},"E":{"sv":[{"v":"Wat verbindt twee botten beweegbaar met elkaar?","o":["Een spier","Een pees","Een gewricht","De huid"],"c":2,"d":2,"u":"Een gewricht verbindt botten beweegbaar.","uo":["Een spier trekt samen.","Een pees verbindt spier en bot.","Klopt: een gewricht verbindt botten beweegbaar.","De huid bedekt het lichaam."],"uh":"Een gewricht verbindt botten beweegbaar."},{"v":"Waarom werken spieren in paren?","o":["Een spier kan alleen trekken","Een spier kan alleen maar duwen","Spieren zijn veel te zwak","Botten bewegen helemaal zelf"],"c":0,"d":3,"u":"Een spier kan alleen trekken, dus je hebt er twee nodig.","uo":["Klopt: een spier kan alleen trekken, dus je hebt er twee nodig.","Een spier duwt niet.","Kracht is niet het probleem.","Botten bewegen niet uit zichzelf."],"uh":"Een spier kan alleen trekken, dus je hebt er twee nodig."},{"v":"Welke spier buigt een gewricht?","o":["De strekspier","De buigspier","De pees","Het gewrichtskapsel"],"c":1,"d":2,"u":"De buigspier buigt.","uo":["De strekspier strekt juist.","Klopt: de buigspier buigt.","Een pees is geen spier.","Het kapsel omhult het gewricht."],"uh":"De buigspier buigt."},{"v":"Wat verbindt een spier met een bot?","o":["Een gewrichtsband","Kraakbeen","Een bloedvat","Een pees"],"c":3,"d":3,"u":"Een pees verbindt spier en bot.","uo":["Een band verbindt botten onderling.","Kraakbeen bedekt botuiteinden.","Een bloedvat vervoert bloed.","Klopt: een pees verbindt spier en bot."],"uh":"Een pees verbindt spier en bot."},{"v":"De knie buigt maar in één richting. Wat voor gewricht is dat?","o":["Een kogelgewricht","Een vast gewricht","Een scharniergewricht","Een spiergewricht"],"c":2,"d":3,"u":"Een scharniergewricht buigt in één richting.","uo":["Een kogelgewricht draait alle kanten op.","Een vast gewricht beweegt niet.","Klopt: een scharniergewricht buigt in één richting.","Een spiergewricht bestaat niet."],"uh":"Een scharniergewricht buigt in één richting."},{"v":"De schouder kan alle kanten op draaien. Wat voor gewricht?","o":["Een kogelgewricht","Een scharniergewricht","Een vast gewricht","Een pees"],"c":0,"d":3,"u":"Een kogelgewricht draait alle kanten op.","uo":["Klopt: een kogelgewricht draait alle kanten op.","Een scharnier buigt in één richting.","Een vast gewricht beweegt niet.","Een pees is geen gewricht."],"uh":"Een kogelgewricht draait alle kanten op."},{"v":"Wat houdt de botten in een gewricht bij elkaar?","o":["Een spier","Een gewrichtsband","Een bloedvat","De opperhuid"],"c":1,"d":2,"u":"Een gewrichtsband houdt botten bijeen.","uo":["Een spier zorgt voor beweging.","Klopt: een gewrichtsband houdt botten bijeen.","Een bloedvat vervoert bloed.","De opperhuid is een huidlaag."],"uh":"Een gewrichtsband houdt botten bijeen."},{"v":"Wat doet de strekspier?","o":["Een gewricht buigen","De huid koelen","Bloed pompen","Een gewricht strekken"],"c":3,"d":2,"u":"De strekspier strekt een gewricht.","uo":["Buigen doet de buigspier.","Koelen doet de huid.","Pompen doet het hart.","Klopt: de strekspier strekt een gewricht."],"uh":"Een gewricht strekken: De strekspier strekt een gewricht."},{"v":"Waarmee zijn de botuiteinden bedekt zodat ze soepel bewegen?","o":["Met spierweefsel","Met huid","Met kraakbeen","Met bloed"],"c":2,"d":2,"u":"Kraakbeen bedekt de botuiteinden.","uo":["Spierweefsel beweegt het bot.","Huid bedekt het lichaam.","Klopt: kraakbeen bedekt de botuiteinden.","Bloed voedt het weefsel."],"uh":"Met kraakbeen: Kraakbeen bedekt de botuiteinden."},{"v":"Wat vermindert de wrijving in een gewricht?","o":["Gewrichtssmeer","Een pees","Een spier","Een bot"],"c":0,"d":2,"u":"Gewrichtssmeer vermindert de wrijving.","uo":["Klopt: gewrichtssmeer vermindert de wrijving.","Een pees verbindt spier en bot.","Een spier zorgt voor beweging.","Een bot geeft steun."],"uh":"Gewrichtssmeer vermindert de wrijving."},{"v":"Twee spieren die tegengesteld werken heten...","o":["synergisten","antagonisten","pezen","banden"],"c":1,"d":1,"u":"Antagonisten werken tegengesteld.","uo":["Synergisten werken juist samen.","Klopt: antagonisten werken tegengesteld.","Pezen verbinden spier en bot.","Banden verbinden botten."],"uh":"Antagonisten werken tegengesteld."},{"v":"Waarom kun je je arm buigen én strekken?","o":["Door één sterke spier","Door de huid","Door een bot","Door een buig- en strekspier"],"c":3,"d":3,"u":"Een buigspier en een strekspier samen.","uo":["Eén spier kan alleen trekken.","De huid beweegt niet.","Een bot beweegt niet zelf.","Klopt: een buigspier en een strekspier samen."],"uh":"Door een buig- en strekspier: Een buigspier en een strekspier samen."},{"v":"Wat is een pees?","o":["Een gewricht in de knie","Buigzaam kraakbeen in het oor","Weefsel dat spier en bot verbindt","Een beschermende huidlaag"],"c":2,"d":2,"u":"Een pees verbindt spier en bot.","uo":["Dat is een gewricht.","Dat is kraakbeen.","Klopt: een pees verbindt spier en bot.","Dat is de huid."],"uh":"Weefsel dat spier en bot verbindt: Een pees verbindt spier en bot."},{"v":"Welke twee delen zorgen samen voor beweging?","o":["Skelet en spieren","Huid en haren","Hart en longen","Nieren en blaas"],"c":0,"d":1,"u":"Het skelet en de spieren.","uo":["Klopt: het skelet en de spieren.","Huid en haren beschermen.","Hart en longen doen iets anders.","Nieren en blaas zuiveren."],"uh":"Skelet en spieren: Het skelet en de spieren."},{"v":"Wat gebeurt er als de buigspier samentrekt?","o":["Het gewricht strekt","Het gewricht buigt","Het bot breekt","De huid koelt af"],"c":1,"d":2,"u":"Het gewricht buigt.","uo":["Strekken doet de strekspier.","Klopt: het gewricht buigt.","Er breekt niets.","De huid heeft hier geen rol."],"uh":"Het gewricht buigt."},{"v":"Waar zit kraakbeen onder andere?","o":["In het hart","In de longen","In het bloed","In het oor"],"c":3,"d":2,"u":"Kraakbeen zit in het oor en de neus.","uo":["Het hart is een spier.","De longen doen gaswisseling.","Bloed is vloeibaar.","Klopt: kraakbeen zit in het oor en de neus."],"uh":"In het oor: Kraakbeen zit in het oor en de neus."}],"begrippen":[{"t":"Gewricht","d":"een beweegbare verbinding tussen twee botten"},{"t":"Gewrichtsband","d":"stevig weefsel dat botten in een gewricht bij elkaar houdt"},{"t":"Pees","d":"stevig weefsel dat een spier aan een bot vastmaakt"},{"t":"Spier","d":"een orgaan dat kan samentrekken en zo beweging maakt"},{"t":"Buigspier","d":"een spier die een gewricht buigt"},{"t":"Strekspier","d":"een spier die een gewricht strekt"},{"t":"Antagonist","d":"een spier die de tegengestelde beweging maakt"},{"t":"Gewrichtskapsel","d":"het omhulsel om een gewricht met smeervloeistof"},{"t":"Gewrichtssmeer","d":"vloeistof die de wrijving in een gewricht verkleint"},{"t":"Kraakbeen","d":"buigzaam steunweefsel dat de botuiteinden bedekt"},{"t":"Scharniergewricht","d":"een gewricht dat maar in één richting buigt, zoals de knie"},{"t":"Kogelgewricht","d":"een gewricht dat in alle richtingen kan draaien, zoals de schouder"}],"sam":"<div class=\"sam-intro\">Het <strong>skelet</strong> en de <strong>spieren</strong> zorgen samen voor beweging. Botten zijn met elkaar verbonden in <strong>gewrichten</strong>, en spieren werken in paren omdat ze alleen kunnen trekken.</div><div class=\"sam-head\">1. Gewrichten en verbindingen</div><p>Waar twee botten beweegbaar samenkomen, zit een <strong>gewricht</strong>. <strong>Gewrichtsbanden</strong> houden de botten bij elkaar, <strong>kraakbeen</strong> bedekt de uiteinden en <strong>gewrichtssmeer</strong> vermindert de wrijving. Een <strong>scharniergewricht</strong> (knie) buigt in één richting, een <strong>kogelgewricht</strong> (schouder) draait alle kanten op.</p><div class=\"sam-head\">2. Spieren werken in paren</div><p>Een <strong>spier</strong> kan alleen trekken, niet duwen. Daarom werken spieren in paren: een <strong>buigspier</strong> buigt een gewricht en de <strong>strekspier</strong> strekt het weer. Zo'n tegenwerkend paar heet een <strong>antagonist</strong>. Een <strong>pees</strong> verbindt de spier met het bot.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gewricht</div><div class=\"sam-definitie-body\">een beweegbare verbinding tussen twee botten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gewrichtsband</div><div class=\"sam-definitie-body\">stevig weefsel dat botten in een gewricht bij elkaar houdt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Pees</div><div class=\"sam-definitie-body\">stevig weefsel dat een spier aan een bot vastmaakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Spier</div><div class=\"sam-definitie-body\">een orgaan dat kan samentrekken en zo beweging maakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Buigspier</div><div class=\"sam-definitie-body\">een spier die een gewricht buigt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Strekspier</div><div class=\"sam-definitie-body\">een spier die een gewricht strekt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Antagonist</div><div class=\"sam-definitie-body\">een spier die de tegengestelde beweging maakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gewrichtskapsel</div><div class=\"sam-definitie-body\">het omhulsel om een gewricht met smeervloeistof.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gewrichtssmeer</div><div class=\"sam-definitie-body\">vloeistof die de wrijving in een gewricht verkleint.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kraakbeen</div><div class=\"sam-definitie-body\">buigzaam steunweefsel dat de botuiteinden bedekt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Scharniergewricht</div><div class=\"sam-definitie-body\">een gewricht dat maar in één richting buigt, zoals de knie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kogelgewricht</div><div class=\"sam-definitie-body\">een gewricht dat in alle richtingen kan draaien, zoals de schouder.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Gewricht»</b> is beweegbare botverbinding, terwijl <b>«Gewrichtsband»</b> houdt botten bijeen is. <b>«Gewrichtsband»</b> is houdt botten bijeen, terwijl <b>«Pees»</b> verbindt spier met bot is. <b>«Spier»</b> is trekt samen, beweegt, terwijl <b>«Pees»</b> verbindt spier met bot is. <b>«Buigspier»</b> is buigt een gewricht, terwijl <b>«Strekspier»</b> strekt een gewricht is.</div>"},"F":{"sv":[{"v":"Wat gebeurt er bij de vertering?","o":["Bloed wordt rondgepompt","Voedsel wordt klein gemaakt","Zuurstof wordt opgenomen","Afval wordt gefilterd"],"c":1,"d":2,"u":"Voedsel wordt klein gemaakt.","uo":["Pompen doet het hart.","Klopt: voedsel wordt klein gemaakt.","Zuurstof nemen de longen op.","Filteren doen de nieren."],"uh":"Voedsel wordt klein gemaakt."},{"v":"Welk bloedvat voert bloed van het hart af?","o":["Een ader","Een haarvat","Een slagader","Een zenuw"],"c":2,"d":2,"u":"Een slagader voert bloed van het hart af.","uo":["Een ader voert bloed naar het hart toe.","In haarvaten wisselen stoffen uit.","Klopt: een slagader voert bloed van het hart af.","Een zenuw is geen bloedvat."],"uh":"Een slagader voert bloed van het hart af."},{"v":"Waar vindt de gaswisseling plaats?","o":["In de longblaasjes","In de maag","In de nieren","In de botten"],"c":0,"d":2,"u":"In de longblaasjes.","uo":["Klopt: in de longblaasjes.","De maag verteert voedsel.","De nieren filteren bloed.","Botten geven steun."],"uh":"In de longblaasjes."},{"v":"Wat doet het hart?","o":["Voedsel verteren","Zuurstof maken","Bloed filteren","Bloed rondpompen"],"c":3,"d":1,"u":"Het hart pompt het bloed rond.","uo":["Verteren doen de darmen.","Zuurstof maak je niet zelf aan.","Filteren doen de nieren.","Klopt: het hart pompt het bloed rond."],"uh":"Bloed rondpompen: Het hart pompt het bloed rond."},{"v":"Wat nemen de darmvlokken op?","o":["Zuurstof","Voedingsstoffen","Afvalstoffen","Botten"],"c":1,"d":2,"u":"Darmvlokken nemen voedingsstoffen op.","uo":["Zuurstof nemen de longen op.","Klopt: darmvlokken nemen voedingsstoffen op.","Afval verlaat juist het lichaam.","Botten worden niet opgenomen."],"uh":"Voedingsstoffen: Darmvlokken nemen voedingsstoffen op."},{"v":"Welk bloedvat voert bloed naar het hart toe?","o":["Een slagader","Een haarvat","Een ader","Een pees"],"c":2,"d":2,"u":"Een ader voert bloed naar het hart.","uo":["Een slagader voert bloed van het hart af.","In haarvaten wisselen stoffen uit.","Klopt: een ader voert bloed naar het hart.","Een pees verbindt spier en bot."],"uh":"Een ader voert bloed naar het hart."},{"v":"Wat filteren de nieren uit het bloed?","o":["Afvalstoffen","Zuurstof","Voedingsstoffen","Botten"],"c":0,"d":2,"u":"De nieren filteren afvalstoffen.","uo":["Klopt: de nieren filteren afvalstoffen.","Zuurstof blijft in het bloed.","Voedingsstoffen worden juist gebruikt.","Botten zitten niet in het bloed."],"uh":"Afvalstoffen: De nieren filteren afvalstoffen."},{"v":"Wat gebeurt er in de longblaasjes?","o":["Voedsel verteren","Bloed filteren","Botten maken","Zuurstof en CO2 wisselen"],"c":3,"d":3,"u":"Zuurstof erin, koolstofdioxide eruit.","uo":["Verteren gebeurt in de darmen.","Filteren doen de nieren.","Botten maakt het beenmerg.","Klopt: zuurstof erin, koolstofdioxide eruit."],"uh":"Zuurstof erin, koolstofdioxide eruit."},{"v":"Wat versnelt de vertering van voedsel?","o":["Botten","Enzymen","Zenuwen","Bloedvaten"],"c":1,"d":2,"u":"Enzymen versnellen de vertering.","uo":["Botten geven steun.","Klopt: enzymen versnellen de vertering.","Zenuwen geven prikkels door.","Bloedvaten vervoeren stoffen."],"uh":"Enzymen versnellen de vertering."},{"v":"Wat stuurt snel met prikkels door het lichaam?","o":["Het bloed","De darmen","Het zenuwstelsel","De huid"],"c":2,"d":2,"u":"Het zenuwstelsel stuurt met prikkels.","uo":["Bloed vervoert stoffen.","De darmen verteren.","Klopt: het zenuwstelsel stuurt met prikkels.","De huid beschermt."],"uh":"Het zenuwstelsel stuurt met prikkels."},{"v":"Hoe regelt een hormoon iets in het lichaam?","o":["Via het bloed","Via de botten","Via de huid","Via de nagels"],"c":0,"d":2,"u":"Een hormoon werkt via het bloed.","uo":["Klopt: een hormoon werkt via het bloed.","Botten geven steun.","De huid beschermt.","Nagels spelen geen rol."],"uh":"Via het bloed: Een hormoon werkt via het bloed."},{"v":"Waar voert een slagader het bloed heen?","o":["Naar het hart toe","Naar de nieren toe","Naar de longen","Van het hart af"],"c":3,"d":3,"u":"Een slagader voert bloed van het hart af.","uo":["Dat doet juist een ader.","Niet specifiek naar de nieren.","Niet specifiek naar de longen.","Klopt: een slagader voert bloed van het hart af."],"uh":"Van het hart af: Een slagader voert bloed van het hart af."},{"v":"Waar worden voedingsstoffen in het bloed opgenomen?","o":["In de longen","In de dunne darm","In het hart","In de nieren"],"c":1,"d":2,"u":"In de dunne darm via darmvlokken.","uo":["In de longen gaat het om zuurstof.","Klopt: in de dunne darm via darmvlokken.","Het hart pompt alleen.","De nieren filteren."],"uh":"In de dunne darm via darmvlokken."},{"v":"Wat is een haarvat?","o":["Een dikke slagader","Een grote ader","Een heel dun bloedvat","Een zenuw"],"c":2,"d":2,"u":"Een haarvat is een heel dun bloedvat.","uo":["Een slagader is juist dik.","Een ader is groter.","Klopt: een haarvat is een heel dun bloedvat.","Een zenuw geeft prikkels door."],"uh":"Een heel dun bloedvat: Een haarvat is een heel dun bloedvat."},{"v":"Wat vervoert het bloed naar de cellen?","o":["Zuurstof en voeding","Alleen botten","Alleen spieren","Alleen huid"],"c":0,"d":1,"u":"Zuurstof en voedingsstoffen.","uo":["Klopt: zuurstof en voedingsstoffen.","Botten worden niet vervoerd.","Spieren worden niet vervoerd.","Huid wordt niet vervoerd."],"uh":"Zuurstof en voedingsstoffen."},{"v":"Welk orgaan neemt zuurstof op uit de lucht?","o":["De maag","De nieren","Het hart","De longen"],"c":3,"d":2,"u":"De longen nemen zuurstof op.","uo":["De maag verteert.","De nieren filteren.","Het hart pompt.","Klopt: de longen nemen zuurstof op."],"uh":"De longen nemen zuurstof op."}],"begrippen":[{"t":"Vertering","d":"het klein maken van voedsel zodat het opgenomen kan worden"},{"t":"Enzym","d":"een stof die een reactie zoals vertering versnelt"},{"t":"Darmvlok","d":"uitstulping in de dunne darm die voedingsstoffen opneemt"},{"t":"Slagader","d":"een bloedvat dat bloed van het hart af vervoert"},{"t":"Ader","d":"een bloedvat dat bloed naar het hart toe vervoert"},{"t":"Haarvat","d":"een heel dun bloedvat waar uitwisseling van stoffen plaatsvindt"},{"t":"Hart","d":"de spier die het bloed rondpompt"},{"t":"Gaswisseling","d":"de opname van zuurstof en afgifte van koolstofdioxide"},{"t":"Longblaasje","d":"klein blaasje in de long waar gaswisseling plaatsvindt"},{"t":"Nier","d":"een orgaan dat afvalstoffen uit het bloed filtert"},{"t":"Zenuwstelsel","d":"het stelsel dat prikkels doorgeeft en het lichaam stuurt"},{"t":"Hormoon","d":"een stof die via het bloed processen in het lichaam regelt"},{"t":"Zintuig","d":"een orgaan dat prikkels uit de omgeving opvangt"}],"sam":"<div class=\"sam-intro\">Organen werken samen om je lichaam draaiende te houden: de <strong>vertering</strong> maakt voedsel klein, het <strong>bloed</strong> vervoert stoffen, de <strong>longen</strong> zorgen voor <strong>gaswisseling</strong> en het <strong>zenuwstelsel</strong> stuurt alles aan.</div><div class=\"sam-head\">1. Vertering en opname</div><p>Bij de <strong>vertering</strong> wordt voedsel klein gemaakt zodat het in het bloed kan worden opgenomen. <strong>Enzymen</strong> versnellen dat proces. In de dunne darm nemen <strong>darmvlokken</strong> de voedingsstoffen op in het bloed.</p><div class=\"sam-head\">2. Bloedsomloop</div><p>Het <strong>hart</strong> pompt het bloed rond. <strong>Slagaders</strong> voeren bloed van het hart af, <strong>aders</strong> voeren het naar het hart toe, en in de dunne <strong>haarvaten</strong> vindt de uitwisseling van stoffen met de cellen plaats.</p><div class=\"sam-head\">3. Gaswisseling en regeling</div><p>In de <strong>longblaasjes</strong> vindt <strong>gaswisseling</strong> plaats: zuurstof gaat het bloed in, koolstofdioxide gaat eruit. De <strong>nieren</strong> filteren afvalstoffen uit het bloed. Het <strong>zenuwstelsel</strong> stuurt snel met prikkels, terwijl <strong>hormonen</strong> langzamer sturen via het bloed.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vertering</div><div class=\"sam-definitie-body\">het klein maken van voedsel zodat het opgenomen kan worden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Enzym</div><div class=\"sam-definitie-body\">een stof die een reactie zoals vertering versnelt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Darmvlok</div><div class=\"sam-definitie-body\">uitstulping in de dunne darm die voedingsstoffen opneemt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Slagader</div><div class=\"sam-definitie-body\">een bloedvat dat bloed van het hart af vervoert.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ader</div><div class=\"sam-definitie-body\">een bloedvat dat bloed naar het hart toe vervoert.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Haarvat</div><div class=\"sam-definitie-body\">een heel dun bloedvat waar uitwisseling van stoffen plaatsvindt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Hart</div><div class=\"sam-definitie-body\">de spier die het bloed rondpompt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gaswisseling</div><div class=\"sam-definitie-body\">de opname van zuurstof en afgifte van koolstofdioxide.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Longblaasje</div><div class=\"sam-definitie-body\">klein blaasje in de long waar gaswisseling plaatsvindt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nier</div><div class=\"sam-definitie-body\">een orgaan dat afvalstoffen uit het bloed filtert.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zenuwstelsel</div><div class=\"sam-definitie-body\">het stelsel dat prikkels doorgeeft en het lichaam stuurt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Hormoon</div><div class=\"sam-definitie-body\">een stof die via het bloed processen in het lichaam regelt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zintuig</div><div class=\"sam-definitie-body\">een orgaan dat prikkels uit de omgeving opvangt.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Enzym»</b> is versnelt een reactie, terwijl <b>«Hormoon»</b> regelt via het bloed is. <b>«Darmvlok»</b> is neemt voeding op, terwijl <b>«Vertering»</b> voedsel klein maken is. <b>«Slagader»</b> is bloed van het hart af, terwijl <b>«Ader»</b> bloed naar het hart toe is. <b>«Haarvat»</b> is uitwisseling van stoffen, terwijl <b>«Slagader»</b> bloed van het hart af is.</div>"},"G":{"sv":[{"v":"Wat is biotechnologie?","o":["Het bestuderen van sterren","Organismen gebruiken om iets te maken","Het bouwen van machines","Het meten van het weer"],"c":1,"d":2,"u":"Organismen inzetten om producten te maken.","uo":["Dat is sterrenkunde.","Klopt: organismen inzetten om producten te maken.","Dat is techniek.","Dat is het weerbericht."],"uh":"Organismen inzetten om producten te maken."},{"v":"Wat doet gist in brood?","o":["Het maakt het brood zout","Het kleurt het brood","Het laat het deeg rijzen","Het koelt het brood af"],"c":2,"d":2,"u":"Gist laat het deeg rijzen.","uo":["Gist maakt het niet zout.","Gist kleurt niet.","Klopt: gist laat het deeg rijzen.","Gist koelt niet."],"uh":"Het laat het deeg rijzen: Gist laat het deeg rijzen."},{"v":"Welk micro-organisme maakt van melk yoghurt?","o":["De melkzuurbacterie","Een schimmel","Een virus","Gist"],"c":0,"d":2,"u":"De melkzuurbacterie maakt yoghurt.","uo":["Klopt: de melkzuurbacterie maakt yoghurt.","Een schimmel maakt o.a. antibiotica.","Een virus maakt ziek.","Gist laat deeg rijzen."],"uh":"De melkzuurbacterie maakt yoghurt."},{"v":"Waar worden antibiotica onder andere van gemaakt?","o":["Van gist","Van melk","Van virussen","Van schimmels"],"c":3,"d":3,"u":"Sommige schimmels maken antibiotica.","uo":["Gist laat deeg rijzen.","Melk wordt yoghurt.","Virussen maken juist ziek.","Klopt: sommige schimmels maken antibiotica."],"uh":"Van schimmels: Sommige schimmels maken antibiotica."},{"v":"Waartegen werkt een antibioticum?","o":["Tegen kou","Tegen bacteriën","Tegen honger","Tegen dorst"],"c":1,"d":1,"u":"Een antibioticum doodt of remt bacteriën.","uo":["Niet tegen kou.","Klopt: een antibioticum doodt of remt bacteriën.","Niet tegen honger.","Niet tegen dorst."],"uh":"Tegen bacteriën: Een antibioticum doodt of remt bacteriën."},{"v":"Wat is genetische modificatie?","o":["Een dier goed voeren","Een plant water geven","Het DNA gericht veranderen","Een dier trainen"],"c":2,"d":2,"u":"Het DNA gericht veranderen.","uo":["Voeren verandert het DNA niet.","Water geven ook niet.","Klopt: het DNA gericht veranderen.","Trainen verandert het DNA niet."],"uh":"Het DNA gericht veranderen."},{"v":"Waarvoor gebruiken we gm-bacteriën onder andere?","o":["Om insuline te maken","Om brood te bakken","Om te sporten","Om te rekenen"],"c":0,"d":3,"u":"Gm-bacteriën maken insuline.","uo":["Klopt: gm-bacteriën maken insuline.","Bakken doet de bakker.","Bacteriën sporten niet.","Bacteriën rekenen niet."],"uh":"Om insuline te maken: Gm-bacteriën maken insuline."},{"v":"Wat is gisting?","o":["Verbranden met zuurstof","Bevriezen van voedsel","Koken van water","Suiker omzetten zonder zuurstof"],"c":3,"d":3,"u":"Suiker omzetten zonder zuurstof.","uo":["Verbranden gebruikt juist zuurstof.","Bevriezen is iets anders.","Koken is iets anders.","Klopt: suiker omzetten zonder zuurstof."],"uh":"Suiker omzetten zonder zuurstof."},{"v":"Wat kan een schimmel maken?","o":["Botten","Antibiotica","Bloed","Spieren"],"c":1,"d":2,"u":"Sommige schimmels maken antibiotica.","uo":["Botten maakt het beenmerg.","Klopt: sommige schimmels maken antibiotica.","Bloed maakt het beenmerg.","Spieren groeien door training."],"uh":"Antibiotica: Sommige schimmels maken antibiotica."},{"v":"Wat is insuline?","o":["Een soort bacterie","Een soort schimmel","Een hormoon voor de bloedsuiker","Een antibioticum"],"c":2,"d":2,"u":"Insuline regelt de bloedsuiker.","uo":["Insuline is geen bacterie.","Ook geen schimmel.","Klopt: insuline regelt de bloedsuiker.","Insuline is geen antibioticum."],"uh":"Een hormoon voor de bloedsuiker: Insuline regelt de bloedsuiker."},{"v":"Wat is een voordeel van gm-gewassen?","o":["Beter tegen droogte","Ze smaken heel zoet","Ze groeien niet meer","Ze worden zwaarder dan lood"],"c":0,"d":3,"u":"Bijvoorbeeld beter tegen droogte.","uo":["Klopt: bijvoorbeeld beter tegen droogte.","Smaak is niet het doel.","Ze groeien juist wel.","Dat is onmogelijk."],"uh":"Beter tegen droogte: Bijvoorbeeld beter tegen droogte."},{"v":"Wat gebeurt er met melk door melkzuurbacteriën?","o":["De melk bevriest","De melk verdampt","De melk wordt gekookt","De melk wordt yoghurt of kaas"],"c":3,"d":2,"u":"De melk wordt yoghurt of kaas.","uo":["Bevriezen is iets anders.","Verdampen is iets anders.","Koken is iets anders.","Klopt: de melk wordt yoghurt of kaas."],"uh":"De melk wordt yoghurt of kaas."},{"v":"Wat betekent resistentie bij bacteriën?","o":["Ze worden beter gevoed","Ze zijn ongevoelig voor antibiotica","Ze worden groter","Ze gaan sneller dood"],"c":1,"d":3,"u":"Ongevoelig voor antibiotica.","uo":["Voeding is niet het punt.","Klopt: ongevoelig voor antibiotica.","Grootte is niet het punt.","Bij resistentie gaan ze juist niet dood."],"uh":"Ze zijn ongevoelig voor antibiotica: Ongevoelig voor antibiotica."},{"v":"Wat doet een vaccin?","o":["Het doodt bacteriën direct","Het geeft je energie","Het traint je afweer","Het maakt je ziek"],"c":2,"d":2,"u":"Een vaccin traint de afweer.","uo":["Dat doet een antibioticum.","Een vaccin geeft geen energie.","Klopt: een vaccin traint de afweer.","Het maakt je juist niet ziek."],"uh":"Het traint je afweer: Een vaccin traint de afweer."},{"v":"Wat is een bacterie?","o":["Eencellig, zonder kern","Een groot dier met botten","Een harde grijze steen","Een glanzend metaal"],"c":0,"d":1,"u":"Eencellig, zonder celkern.","uo":["Klopt: eencellig, zonder celkern.","Een bacterie is geen groot dier.","Een bacterie leeft.","Een bacterie is geen metaal."],"uh":"Eencellig, zonder celkern."},{"v":"Waarom is te veel antibiotica gebruiken een probleem?","o":["Het voedt de bacteriën","Het maakt bacteriën groter","Het maakt bacteriën sneller","Bacteriën worden resistent"],"c":3,"d":3,"u":"Bacteriën worden ongevoelig (resistent).","uo":["Het voedt ze niet.","Grootte is niet het punt.","Snelheid is niet het punt.","Klopt: bacteriën worden ongevoelig (resistent)."],"uh":"Bacteriën worden ongevoelig (resistent)."}],"begrippen":[{"t":"Biotechnologie","d":"het gebruik van organismen om producten te maken"},{"t":"Gist","d":"een schimmel die suiker omzet en deeg laat rijzen"},{"t":"Melkzuurbacterie","d":"een bacterie die melk in yoghurt of kaas omzet"},{"t":"Gisting","d":"het omzetten van suiker door micro-organismen zonder zuurstof"},{"t":"Antibioticum","d":"een stof die bacteriën doodt of hun groei remt"},{"t":"Schimmel","d":"een organisme dat stoffen zoals antibiotica kan maken"},{"t":"Genetische modificatie","d":"het gericht veranderen van het DNA van een organisme"},{"t":"Insuline","d":"een hormoon dat met gm-bacteriën gemaakt kan worden"},{"t":"Gm-gewas","d":"een gewas met gericht veranderd DNA"},{"t":"Resistentie","d":"ongevoeligheid van bacteriën voor een antibioticum"},{"t":"Vaccin","d":"een middel dat je afweer traint tegen een ziekteverwekker"},{"t":"Bacterie","d":"een eencellig organisme zonder celkern"}],"sam":"<div class=\"sam-intro\">Mensen zetten organismen aan het werk in de <strong>biotechnologie</strong>: <strong>gist</strong> en <strong>melkzuurbacteriën</strong> in voeding, <strong>schimmels</strong> voor <strong>antibiotica</strong> en <strong>genetische modificatie</strong> om stoffen zoals <strong>insuline</strong> te maken.</div><div class=\"sam-head\">1. Micro-organismen in voeding</div><p><strong>Biotechnologie</strong> is het gebruik van organismen om producten te maken. <strong>Gist</strong> is een schimmel die suiker omzet en deeg laat rijzen; <strong>melkzuurbacteriën</strong> maken van melk yoghurt en kaas. Dit omzetten zonder zuurstof heet <strong>gisting</strong>.</p><div class=\"sam-head\">2. Medicijnen en modificatie</div><p>Sommige <strong>schimmels</strong> maken <strong>antibiotica</strong>, stoffen die bacteriën doden of hun groei remmen. Bij <strong>genetische modificatie</strong> verander je gericht het DNA van een organisme, bijvoorbeeld om bacteriën <strong>insuline</strong> te laten maken voor mensen met diabetes.</p><p>Genetische modificatie heeft voor- en nadelen. <strong>Gm-gewassen</strong> kunnen bijvoorbeeld beter tegen droogte, maar er zijn ook zorgen over gevolgen voor natuur en gezondheid. Overmatig antibioticagebruik leidt tot <strong>resistentie</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Biotechnologie</div><div class=\"sam-definitie-body\">het gebruik van organismen om producten te maken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gist</div><div class=\"sam-definitie-body\">een schimmel die suiker omzet en deeg laat rijzen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Melkzuurbacterie</div><div class=\"sam-definitie-body\">een bacterie die melk in yoghurt of kaas omzet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gisting</div><div class=\"sam-definitie-body\">het omzetten van suiker door micro-organismen zonder zuurstof.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Antibioticum</div><div class=\"sam-definitie-body\">een stof die bacteriën doodt of hun groei remt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Schimmel</div><div class=\"sam-definitie-body\">een organisme dat stoffen zoals antibiotica kan maken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Genetische modificatie</div><div class=\"sam-definitie-body\">het gericht veranderen van het DNA van een organisme.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Insuline</div><div class=\"sam-definitie-body\">een hormoon dat met gm-bacteriën gemaakt kan worden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gm-gewas</div><div class=\"sam-definitie-body\">een gewas met gericht veranderd DNA.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Resistentie</div><div class=\"sam-definitie-body\">ongevoeligheid van bacteriën voor een antibioticum.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vaccin</div><div class=\"sam-definitie-body\">een middel dat je afweer traint tegen een ziekteverwekker.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bacterie</div><div class=\"sam-definitie-body\">een eencellig organisme zonder celkern.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Biotechnologie»</b> is organismen als fabriekje, terwijl <b>«Genetische modificatie»</b> DNA gericht veranderen is. <b>«Gist»</b> is laat deeg rijzen, terwijl <b>«Melkzuurbacterie»</b> maakt yoghurt en kaas is. <b>«Antibioticum»</b> is werkt tegen bacteriën, terwijl <b>«Vaccin»</b> traint de afweer is. <b>«Schimmel»</b> is maakt o.a. antibiotica, terwijl <b>«Bacterie»</b> eencellig, geen kern is.</div>"}});